   CSS Custom Properties
============================================================ */
:root {
  --bg-page:        #0d0f13;
  --bg-card:        #161920;
  --bg-card-raised: #1e2229;
  --bg-overlay:     rgba(0, 0, 0, 0.72);

  --border:         #2a2d35;
  --border-hover:   #3f4351;

  --text-primary:   #e8eaf0;
  --text-secondary: #8a8f9e;
  --text-muted:     #555b6b;

  --accent-red:     #e05252;
  --accent-red-hover: #c94343;
  --accent-red-subtle: rgba(224, 82, 82, 0.12);
  --accent-red-ring:   rgba(224, 82, 82, 0.4);

  --focus-ring:     #5b8af5;
  --focus-ring-width: 2px;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;

  --shadow-card:   0 2px 16px rgba(0,0,0,0.5);
  --shadow-dialog: 0 24px 64px rgba(0,0,0,0.8), 0 4px 16px rgba(0,0,0,0.6);

  --transition: 180ms ease;
  --transition-slow: 260ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* ============================================================
   Reset & Base
============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  color-scheme: dark;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  background-color: var(--bg-page);
  color: var(--text-primary);
  min-height: 100dvh;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

/* ============================================================
   Focus Visible
============================================================ */
:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Page Layout
============================================================ */
#app {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

.page-header {
  border-bottom: 1px solid var(--border);
  padding: 14px 28px;
}

.breadcrumb {
  list-style: none;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-secondary);
}

.breadcrumb li:nth-child(2) {
  color: var(--text-muted);
  user-select: none;
}

.breadcrumb a {
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}

.breadcrumb a:hover {
  color: var(--text-primary);
}

[aria-current="page"] {
  color: var(--text-primary);
}

.page-main {
  flex: 1;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 24px;
}

/* ============================================================
   Image Preview Card
============================================================ */
.image-preview-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  width: 100%;
  max-width: 620px;
}

.preview-figure {
  position: relative;
  background: #0a0b0e;
  line-height: 0;
}

.preview-image {
  width: 100%;
  height: 340px;
  object-fit: cover;
  display: block;
}

.preview-caption {
  position: absolute;
  bottom: 12px;
  left: 14px;
  font-size: 12px;
  color: rgba(255,255,255,0.75);
  background: rgba(0,0,0,0.55);
  backdrop-filter: blur(6px);
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.02em;
}

/* ============================================================
   Image Meta
============================================================ */
.image-meta {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.meta-item {
  flex: 1;
  padding: 16px 20px;
  border-right: 1px solid var(--border);
}

.meta-item:last-child {
  border-right: none;
}

.meta-item dt {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.meta-item dd {
  font-size: 13px;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

/* ============================================================
   Image Actions
============================================================ */
.image-actions {
  display: flex;
  gap: 10px;
  padding: 18px 20px;
  justify-content: flex-end;
}

/* ============================================================
   Buttons
============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  font-size: 13.5px;
  font-weight: 500;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition), box-shadow var(--transition);
  white-space: nowrap;
  letter-spacing: 0.01em;
  line-height: 1;
}

.btn svg {
  flex-shrink: 0;
}

.btn-secondary {
  background: var(--bg-card-raised);
  border-color: var(--border);
  color: var(--text-secondary);
}

.btn-secondary:hover {
  background: #252931;
  border-color: var(--border-hover);
  color: var(--text-primary);
}

.btn-danger {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}

.btn-danger:hover {
  background: var(--accent-red-hover);
  border-color: var(--accent-red-hover);
  box-shadow: 0 0 0 3px var(--accent-red-ring);
}

/* ============================================================
   Dialog Backdrop
============================================================ */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;

  /* Hidden by default */
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
}

.dialog-backdrop.is-open {
  opacity: 1;
  pointer-events: auto;
}

/* ============================================================
   Dialog Panel
============================================================ */
.dialog {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  width: 100%;
  max-width: 420px;
  outline: none;

  transform: translateY(10px) scale(0.97);
  transition: transform var(--transition-slow);
}

.dialog-backdrop.is-open .dialog {
  transform: translateY(0) scale(1);
}

/* ============================================================
   Dialog Header
============================================================ */
.dialog-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border);
  position: relative;
}

.dialog-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dialog-icon--danger {
  background: var(--accent-red-subtle);
  color: var(--accent-red);
  border: 1px solid rgba(224, 82, 82, 0.2);
}

.dialog-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.3;
  flex: 1;
}

.dialog-close {
  position: absolute;
  top: 14px;
  right: 14px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: var(--radius-sm);
  padding: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}

.dialog-close:hover {
  background: var(--bg-card-raised);
  border-color: var(--border);
  color: var(--text-primary);
}

/* ============================================================
   Dialog Body
============================================================ */
.dialog-body {
  padding: 20px;
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.dialog-desc {
  flex: 1;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.65;
}

.dialog-desc strong {
  color: var(--text-primary);
  font-weight: 600;
  word-break: break-all;
}

.dialog-preview-thumb {
  flex-shrink: 0;
  width: 68px;
  height: 68px;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border);
}

.dialog-preview-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ============================================================
   Dialog Footer
============================================================ */
.dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 20px 20px;
  border-top: 1px solid var(--border);
}

/* ============================================================
   Reduced Motion
============================================================ */
@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop,
  .dialog {
    transition: none;
  }
}
