/* ── State ────────────────────────────────────────────────── */
const DialogController = (() => {
  const backdrop      = document.getElementById('dialog-backdrop');
  const dialog        = document.getElementById('delete-dialog');
  const openBtn       = document.getElementById('open-dialog-btn');
  const closeBtn      = document.getElementById('close-dialog-btn');
  const cancelBtn     = document.getElementById('cancel-btn');
  const confirmBtn    = document.getElementById('confirm-delete-btn');

  let previouslyFocused = null;

  // All focusable elements inside the dialog
  const FOCUSABLE = 'a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])';

  /* ── Open ───────────────────────────────────────────────── */
  function open() {
    previouslyFocused = document.activeElement;

    backdrop.classList.add('is-open');
    backdrop.setAttribute('aria-hidden', 'false');

    // Move focus into the dialog after the CSS transition starts
    requestAnimationFrame(() => {
      dialog.focus();
    });

    document.addEventListener('keydown', handleKeydown);
  }

  /* ── Close ──────────────────────────────────────────────── */
  function close() {
    backdrop.classList.remove('is-open');
    backdrop.setAttribute('aria-hidden', 'true');

    document.removeEventListener('keydown', handleKeydown);

    // Return focus to the element that opened the dialog
    if (previouslyFocused) {
      previouslyFocused.focus();
      previouslyFocused = null;
    }
  }

  /* ── Focus Trap ─────────────────────────────────────────── */
  function trapFocus(event) {
    const focusable = Array.from(dialog.querySelectorAll(FOCUSABLE));
    if (!focusable.length) return;

    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (event.shiftKey) {
      // Shift+Tab — wrap to last
      if (document.activeElement === first) {
        event.preventDefault();
        last.focus();
      }
    } else {
      // Tab — wrap to first
      if (document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
  }

  /* ── Keyboard Handler ───────────────────────────────────── */
  function handleKeydown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      close();
      return;
    }
    if (event.key === 'Tab') {
      trapFocus(event);
    }
  }

  /* ── Backdrop click to dismiss ──────────────────────────── */
  backdrop.addEventListener('click', (event) => {
    if (event.target === backdrop) {
      close();
    }
  });

  /* ── Confirm (delete) action ────────────────────────────── */
  function handleConfirmDelete() {
    // Simulate delete — in a real app this would call an API
    confirmBtn.textContent = 'Deleting…';
    confirmBtn.disabled = true;

    setTimeout(() => {
      close();
      // Reset button state after dialog closes
      setTimeout(() => {
        confirmBtn.innerHTML = `
          <svg aria-hidden="true" focusable="false" width="15" height="15"
               viewBox="0 0 24 24" fill="none" stroke="currentColor"
               stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
            <polyline points="3 6 5 6 21 6"/>
            <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
          </svg>
          Yes, Delete`;
        confirmBtn.disabled = false;
      }, 300);
    }, 800);
  }

  /* ── Wire up controls ───────────────────────────────────── */
  function bindTrigger() {
    openBtn.addEventListener('click', open);
    closeBtn.addEventListener('click', close);
    cancelBtn.addEventListener('click', close);
    confirmBtn.addEventListener('click', handleConfirmDelete);
  }

  return { bindTrigger };
})();

